<?php
require_once __DIR__ . '/../config/app.php';
require_module_access('pos');
ensure_vendor_day_closure_schema();

$vendor=current_vendor_profile();
$isOwner=current_user_role()==='vendor'&&$vendor&&(int)$vendor['user_id']===(int)current_user_id();
if(!$isOwner&&!is_super_admin()){http_response_code(403);exit('Only a vendor account owner or Super Admin may access day closures.');}
$today=app_business_date();
$error='';$message='';
$historyView=$isOwner&&(string)($_GET['view']??'')==='history';
$auditView=is_super_admin()&&(string)($_GET['view']??'')==='audit';
$auditMode=$auditView&&in_array((string)($_GET['mode']??''),['lookup','type'],true)?(string)$_GET['mode']:'';
$auditSearch=trim((string)($_GET['q']??''));
$auditFrom=(string)($_GET['from']??date('Y-m-d',strtotime($today.' -30 days')));
$auditTo=(string)($_GET['to']??$today);
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$auditFrom))$auditFrom=date('Y-m-d',strtotime($today.' -30 days'));
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$auditTo))$auditTo=$today;

if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!verify_csrf_token((string)($_POST['csrf_token']??'')))$error='Your session expired. Please try again.';
    elseif($historyView||$auditView)$error='This report is read-only.';
    elseif((string)($_POST['action']??'')==='close'){
        if(!$isOwner)$error='Only the vendor account owner can close sales for the day.';
        elseif((string)($_POST['confirm_close']??'')!=='1')$error='Confirm that you want to close sales for today.';
        else{
            $vendorId=(int)$vendor['id'];$lockName=vendor_day_lock_name($vendorId,$today);
            try{
                $lock=db()->prepare('SELECT GET_LOCK(?,10)');$lock->execute([$lockName]);if((int)$lock->fetchColumn()!==1)throw new RuntimeException('The close-day lock could not be acquired.');
                db()->beginTransaction();
                if(vendor_day_is_closed($vendorId,$today))throw new DomainException('Sales are already closed for this vendor today.');
                $summary=vendor_day_summary($vendorId,$today);$summary['vendor']=['id'=>$vendorId,'name'=>(string)$vendor['vendor_name']];$summary['closed_by']=['user_id'=>(int)current_user_id(),'name'=>current_user_name()];$summary['closed_at']=(new DateTimeImmutable('now'))->format('Y-m-d H:i:s');$summary['timezone']=date_default_timezone_get();
                $sequence=db()->prepare('SELECT COALESCE(MAX(closure_sequence),0)+1 FROM vendor_day_closures WHERE vendor_id=? AND business_date=?');$sequence->execute([$vendorId,$today]);
                db()->prepare('INSERT INTO vendor_day_closures(vendor_id,business_date,closure_sequence,closed_by_user_id,closed_by_user_name,closed_at,summary_snapshot) VALUES(?,?,?,?,?,NOW(),?)')->execute([$vendorId,$today,(int)$sequence->fetchColumn(),current_user_id(),current_user_name(),json_encode($summary,JSON_THROW_ON_ERROR|JSON_PRESERVE_ZERO_FRACTION)]);
                db()->commit();$message='Sales have been closed for today.';
            }catch(Throwable $exception){if(db()->inTransaction())db()->rollBack();$error=$exception instanceof DomainException?$exception->getMessage():'The day could not be closed. Please try again.';}
            finally{$release=db()->prepare('SELECT RELEASE_LOCK(?)');$release->execute([$lockName]);}
        }
    }elseif((string)($_POST['action']??'')==='reopen'){
        if(!is_super_admin())$error='Only Super Admin can reopen a closed day.';
        else{
            $closureId=max(0,(int)($_POST['closure_id']??0));$reason=trim((string)($_POST['reason']??''));
            if($reason==='')$error='Enter a reason for reopening the day.';
            else try{
                db()->beginTransaction();
                $find=db()->prepare('SELECT * FROM vendor_day_closures WHERE id=? FOR UPDATE');$find->execute([$closureId]);$closure=$find->fetch();
                if(!$closure||$closure['reopened_at']!==null)throw new DomainException('That closure is no longer active.');
                db()->prepare('UPDATE vendor_day_closures SET reopened_by_user_id=?,reopened_by_user_name=?,reopened_at=NOW(),reopen_reason=? WHERE id=? AND reopened_at IS NULL')->execute([current_user_id(),current_user_name(),$reason,$closureId]);
                db()->prepare("INSERT INTO vendor_day_closure_audit(closure_id,action,administrator_user_id,administrator_user_name,reason,action_at) VALUES(?,'reopened',?,?,?,NOW())")->execute([$closureId,current_user_id(),current_user_name(),$reason]);
                db()->commit();$message='The vendor day has been reopened.';
            }catch(Throwable $exception){if(db()->inTransaction())db()->rollBack();$error=$exception instanceof DomainException?$exception->getMessage():'The day could not be reopened.';}
        }
    }
}

$activeClosure=$isOwner?vendor_day_is_closed((int)$vendor['id'],$today):null;
$summary=$isOwner?($activeClosure?(json_decode((string)$activeClosure['summary_snapshot'],true)?:vendor_day_summary((int)$vendor['id'],$today)):vendor_day_summary((int)$vendor['id'],$today)):null;
$closures=[];$auditRows=[];$vendorClosures=[];
if($isOwner){
    $vendorClosureStatement=db()->prepare("SELECT c.*,COALESCE(NULLIF(c.closed_by_user_name,''),closer.full_name,'Unknown') closed_by,COALESCE(NULLIF(c.reopened_by_user_name,''),reopener.full_name,'Super Admin') reopened_by FROM vendor_day_closures c LEFT JOIN users closer ON closer.id=c.closed_by_user_id LEFT JOIN users reopener ON reopener.id=c.reopened_by_user_id WHERE c.vendor_id=? ORDER BY c.business_date DESC,c.closed_at DESC,c.id DESC");
    $vendorClosureStatement->execute([(int)$vendor['id']]);$vendorClosures=$vendorClosureStatement->fetchAll();
}
if(is_super_admin()){
    $closures=db()->query("SELECT c.*,v.vendor_name,COALESCE(NULLIF(c.closed_by_user_name,''),closer.full_name) closed_by,COALESCE(NULLIF(c.reopened_by_user_name,''),reopener.full_name) reopened_by FROM vendor_day_closures c INNER JOIN vendors v ON v.id=c.vendor_id LEFT JOIN users closer ON closer.id=c.closed_by_user_id LEFT JOIN users reopener ON reopener.id=c.reopened_by_user_id ORDER BY c.business_date DESC,c.closed_at DESC,c.id DESC")->fetchAll();
    $auditSelect="SELECT a.*,c.business_date,c.closure_sequence,v.vendor_name,COALESCE(NULLIF(a.administrator_user_name,''),u.full_name,'Unknown') administrator_name FROM vendor_day_closure_audit a INNER JOIN vendor_day_closures c ON c.id=a.closure_id INNER JOIN vendors v ON v.id=c.vendor_id LEFT JOIN users u ON u.id=a.administrator_user_id";
    if($auditView&&$auditMode==='lookup'){
        $auditStatement=db()->prepare($auditSelect.' WHERE DATE(a.action_at) BETWEEN ? AND ? ORDER BY a.action_at DESC,a.id DESC');
        $auditStatement->execute([$auditFrom,$auditTo]);$auditRows=$auditStatement->fetchAll();
    }elseif($auditView&&$auditMode==='type'&&$auditSearch!==''){
        $term='%'.$auditSearch.'%';
        $auditStatement=db()->prepare($auditSelect." WHERE v.vendor_name LIKE ? OR COALESCE(NULLIF(a.administrator_user_name,''),u.full_name,'Unknown') LIKE ? OR a.reason LIKE ? OR DATE_FORMAT(a.action_at,'%d %b %Y %H:%i:%s') LIKE ? OR DATE_FORMAT(c.business_date,'%d %b %Y') LIKE ? OR CAST(c.closure_sequence AS CHAR) LIKE ? ORDER BY a.action_at DESC,a.id DESC");
        $auditStatement->execute([$term,$term,$term,$term,$term,$term]);$auditRows=$auditStatement->fetchAll();
    }
}
$pageTitle=$auditView?'Reopening Audit Trail':($historyView?'Day Closure Reports':($isOwner?'Close Day':'Vendor Day Closures'));$closeDayParentUrl=($historyView||$auditView)?app_url('pos.php?view=reports'):($isOwner?app_url((string)($vendor['vendor_type']??'regular')==='sor'?'pos.php?view=sor':'pos.php?view=sales'):app_url('pos.php?view=admin'));$closeDayParentLabel=($historyView||$auditView)?'Reports':($isOwner&&((string)($vendor['vendor_type']??'regular')==='sor')?'SoR':($isOwner?'Direct Sales':'Admin'));$breadcrumbs=[['label'=>'Home','url'=>app_url('index.php')],['label'=>'POS','url'=>app_url('pos.php')],['label'=>$closeDayParentLabel,'url'=>$closeDayParentUrl],['label'=>$pageTitle]];$internalBackUrl=$closeDayParentUrl;
require_once __DIR__ . '/../includes/header.php';
function closure_money(mixed $value):string{return 'GHS '.number_format((float)$value,2);}
?>
<section class="management-panel close-day-page <?=$isOwner?'close-day-page--owner':'close-day-page--admin'?>"><div class="management-heading close-day-hero"><div><span class="section-kicker">SPW Sales · <?=($historyView||$auditView)?'Reports':'End of day'?></span><h1><?=e($pageTitle)?></h1><p><?=e($auditView?'Permanent Super Admin reopening history':($historyView?(string)$vendor['vendor_name'].' · Complete day closure history':($isOwner?(string)$vendor['vendor_name'].' · '.date('l, d F Y',strtotime($today)):'Review every vendor closure, immutable snapshot, and reopening record.')))?></p></div><div class="management-icon close-day-hero__icon"><i class="fa-solid <?=$auditView?'fa-clock-rotate-left':($historyView?'fa-chart-column':($activeClosure?'fa-lock':'fa-calendar-check'))?>"></i></div></div>
<?php if($message):?><div class="profile-message is-success"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="profile-message is-error"><?=e($error)?></div><?php endif;?>
<?php if($auditView):?>
<?php if($auditMode===''):?>
<div class="report-mode-actions report-mode-actions--menu pos-report-mode-menu"><a class="report-mode-button" href="<?=e(app_url('close-day.php?view=audit&mode=lookup'))?>"><i class="fa-solid fa-list-check"></i><span>Lookup</span></a><a class="report-mode-button" href="<?=e(app_url('close-day.php?view=audit&mode=type'))?>"><i class="fa-solid fa-keyboard"></i><span>Quick Search</span></a></div>
<?php else:?>
<?php if($auditMode==='type'):?><form class="pos-report-filter pos-report-filter--quick" method="get" data-pos-live-filter="search"><input type="hidden" name="view" value="audit"><input type="hidden" name="mode" value="type"><label class="pos-report-filter__search">Quick Search<input type="search" name="q" value="<?=e($auditSearch)?>" placeholder="Vendor, administrator, reason, date or sequence" autocomplete="off" autofocus></label><button class="login-button" type="submit"><i class="fa-solid fa-magnifying-glass"></i><span>Search</span></button></form><?php else:?><form class="pos-report-filter" method="get" data-pos-live-filter="date"><input type="hidden" name="view" value="audit"><input type="hidden" name="mode" value="lookup"><div class="pos-report-filter__row pos-report-filter__row--date"><label>From<input type="date" name="from" value="<?=e($auditFrom)?>"></label><label>To<input type="date" name="to" value="<?=e($auditTo)?>"></label></div><button class="login-button" type="submit"><i class="fa-solid fa-filter"></i><span>Show</span></button></form><?php endif;?>
<p class="report-result-count pos-report-result-count"><?=number_format(count($auditRows))?> result<?=count($auditRows)===1?'':'s'?> found</p>
<div class="close-day-section close-day-audit"><div class="table-wrap"><table class="data-table"><thead><tr><th>Action time</th><th>Vendor</th><th>Business date</th><th>Closure sequence</th><th>Administrator</th><th>Reason</th></tr></thead><tbody><?php foreach($auditRows as $audit):?><tr><td><strong><?=e(date('d M Y',strtotime((string)$audit['action_at'])))?></strong><span class="muted-text"><?=e(date('H:i:s',strtotime((string)$audit['action_at'])))?></span></td><td><strong><?=e((string)$audit['vendor_name'])?></strong></td><td><?=e(date('d M Y',strtotime((string)$audit['business_date'])))?></td><td><strong>Sequence <?=(int)$audit['closure_sequence']?></strong></td><td><strong><?=e((string)$audit['administrator_name'])?></strong></td><td><?=nl2br(e((string)$audit['reason']))?></td></tr><?php endforeach;?><?php if(!$auditRows):?><tr><td colspan="6" class="empty-state"><?= $auditMode==='type'&&$auditSearch===''?'Type a vendor, administrator, reason, date or sequence to search.':'No reopening actions found for this lookup.' ?></td></tr><?php endif;?></tbody></table></div></div>
<?php endif;?>
<?php elseif($historyView):?>
<div class="close-day-section close-day-vendor-history"><div class="close-day-section__heading"><span><i class="fa-solid fa-clock-rotate-left"></i></span><div><h2>Your closure history</h2><p>Read-only records and snapshots for <?=e((string)$vendor['vendor_name'])?>.</p></div><span class="status-badge is-active"><?=number_format(count($vendorClosures))?> record<?=count($vendorClosures)===1?'':'s'?></span></div><div class="closure-history-list"><?php foreach($vendorClosures as $history):$historySnapshot=json_decode((string)$history['summary_snapshot'],true)?:[];?><article class="closure-history-card"><header class="closure-history-card__header"><div class="closure-history-card__date"><span><i class="fa-solid fa-calendar-day"></i></span><div><small>Business date</small><strong><?=e(date('l, d F Y',strtotime((string)$history['business_date'])))?></strong></div></div><span class="status-badge <?=$history['reopened_at']?'is-warning':'is-inactive'?>"><i class="fa-solid <?=$history['reopened_at']?'fa-lock-open':'fa-lock'?>"></i><?=$history['reopened_at']?'Reopened':'Closed'?></span></header><div class="closure-history-card__meta"><div><small>Closed at</small><strong><?=e(date('H:i',strtotime((string)$history['closed_at'])))?></strong></div><div><small>Closed by</small><strong><?=e((string)$history['closed_by'])?></strong></div><div><small>Sales</small><strong><?=number_format((int)($historySnapshot['sale_count']??0))?></strong></div></div><div class="closure-history-card__totals"><?php foreach([['Gross sales',$historySnapshot['gross_sales']??0],['Delivery',$historySnapshot['delivery_charges']??0],['Net sales',$historySnapshot['net_sales']??0],['Discount / commission',$historySnapshot['discounts_commissions']??0],['Final total',$historySnapshot['amount_less_commission']??0]] as [$label,$amount]):?><div><small><?=e($label)?></small><strong><?=e(closure_money($amount))?></strong></div><?php endforeach;?></div><?php if($history['reopened_at']):?><div class="closure-history-card__reopen"><i class="fa-solid fa-circle-info"></i><div><strong>Reopened <?=e(date('d M Y H:i',strtotime((string)$history['reopened_at'])))?></strong><p><?=e((string)$history['reopen_reason'])?></p></div></div><?php endif;?><details class="closure-history-details"><summary><span><i class="fa-solid fa-list-check"></i>View products and personnel</span><i class="fa-solid fa-chevron-down"></i></summary><div class="closure-history-details__grid"><section><h3>Products sold</h3><?php foreach(($historySnapshot['products']??[]) as $product):?><div class="closure-history-line"><span><?=e($product['brand_name'].' '.$product['plug_number'])?></span><strong>× <?=number_format((int)$product['quantity'])?></strong></div><?php endforeach;?><?php if(empty($historySnapshot['products'])):?><p class="empty-state">No products recorded.</p><?php endif;?></section><section><h3>Personnel totals</h3><?php foreach(($historySnapshot['personnel']??[]) as $person):?><div class="closure-history-line"><span><?=e($person['personnel_name'])?><small><?=number_format((int)$person['sale_count'])?> sale<?=((int)$person['sale_count']===1)?'':'s'?></small></span><strong><?=e(closure_money($person['net_sales']))?></strong></div><?php endforeach;?><?php if(empty($historySnapshot['personnel'])):?><p class="empty-state">No personnel totals recorded.</p><?php endif;?></section></div></details></article><?php endforeach;?><?php if(!$vendorClosures):?><div class="closure-history-empty"><span><i class="fa-solid fa-calendar-xmark"></i></span><h3>No closure history yet</h3><p>Your completed Close Day records will appear here.</p></div><?php endif;?></div></div>
<?php elseif($isOwner):?>
<div class="close-day-status <?=$activeClosure?'is-closed':'is-open'?>"><span class="close-day-status__icon"><i class="fa-solid <?=$activeClosure?'fa-lock':'fa-lock-open'?>"></i></span><div><strong><?=$activeClosure?'Sales are closed':'Sales are open'?></strong><span><?=$activeClosure?'Closed at '.e(date('H:i',strtotime((string)$activeClosure['closed_at']))).' · Snapshot preserved':'Review every figure below before closing today’s sales.'?></span></div><span class="status-badge <?=$activeClosure?'is-inactive':'is-active'?>"><?=$activeClosure?'Closed':'Open'?></span></div>
<div class="summary-grid close-day-summary"><?php foreach([['fa-receipt','Sales',$summary['sale_count']],['fa-coins','Gross sales',closure_money($summary['gross_sales'])],['fa-truck','Delivery charges',closure_money($summary['delivery_charges'])],['fa-chart-line','Net sales',closure_money($summary['net_sales'])],['fa-percent','Discounts / commissions',closure_money($summary['discounts_commissions'])],['fa-wallet','Final total',closure_money($summary['amount_less_commission'])]] as [$icon,$label,$value]):?><div class="summary-card"><span class="summary-card__icon"><i class="fa-solid <?=e($icon)?>"></i></span><span><?=e((string)$label)?></span><strong><?=e((string)$value)?></strong></div><?php endforeach;?></div>
<div class="close-day-section"><div class="close-day-section__heading"><span><i class="fa-solid fa-boxes-stacked"></i></span><div><h2>Products and quantities</h2><p>Consolidated items sold during this business day.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Product</th><th>Quantity</th><th>Gross</th></tr></thead><tbody><?php foreach($summary['products'] as $row):?><tr><td><strong><?=e($row['brand_name'].' '.$row['plug_number'])?></strong></td><td><span class="close-day-quantity"><?=number_format((int)$row['quantity'])?></span></td><td><?=e(closure_money($row['gross_amount']))?></td></tr><?php endforeach;?><?php if(!$summary['products']):?><tr><td colspan="3" class="empty-state">No products sold today.</td></tr><?php endif;?></tbody></table></div></div>
<div class="close-day-section"><div class="close-day-section__heading"><span><i class="fa-solid fa-people-group"></i></span><div><h2>Totals by personnel</h2><p>Accountability totals for the owner and assigned personnel.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Personnel</th><th>Sales</th><th>Gross</th><th>Delivery</th><th>Net</th><th>Discount / commission</th><th>Total</th></tr></thead><tbody><?php foreach($summary['personnel'] as $row):?><tr><td><strong><?=e($row['personnel_name'])?></strong></td><td><?=number_format((int)$row['sale_count'])?></td><td><?=e(closure_money($row['gross_sales']))?></td><td><?=e(closure_money($row['delivery_charges']))?></td><td><strong><?=e(closure_money($row['net_sales']))?></strong></td><td><?=e(closure_money($row['discounts_commissions']))?></td><td><strong><?=e(closure_money($row['total_after_commission']))?></strong></td></tr><?php endforeach;?><?php if(!$summary['personnel']):?><tr><td colspan="7" class="empty-state">No personnel sales today.</td></tr><?php endif;?></tbody></table></div></div>
<?php if($activeClosure):?><div class="close-day-action is-closed"><span><i class="fa-solid fa-circle-check"></i></span><div><strong>Day successfully closed</strong><p>No new sales can be recorded by this vendor or its personnel until tomorrow.</p></div><button class="login-button" type="button" disabled><i class="fa-solid fa-lock"></i><span>Sales Closed · <?=e(date('H:i',strtotime((string)$activeClosure['closed_at'])))?></span></button></div><?php else:?><form class="close-day-action" method="post" data-confirm-title="Close sales for today?" data-confirm-message="This blocks the owner and all assigned personnel from recording new sales until the next calendar day."><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="close"><div class="close-day-action__copy"><span><i class="fa-solid fa-shield-halved"></i></span><div><strong>Ready to close?</strong><p>This creates an immutable snapshot and blocks all new vendor sales for the rest of today.</p></div></div><label class="standalone-promo-choice"><input type="checkbox" name="confirm_close" value="1" required><span><strong>I confirm this complete daily summary</strong><small>I have reviewed the products, channels, and personnel totals above.</small></span></label><button class="login-button" type="submit"><i class="fa-solid fa-lock"></i><span>Close Sales for Today</span></button></form><?php endif;?>
<?php else:?><div class="close-day-admin-intro"><span><i class="fa-solid fa-shield-halved"></i></span><div><strong>Super Admin closure register</strong><p><?=number_format(count($closures))?> closure record<?=count($closures)===1?'':'s'?>. Reopening requires a reason and is permanently audited.</p></div></div><div class="table-wrap close-day-admin-table"><table class="data-table"><thead><tr><th>Date</th><th>Vendor</th><th>Closed</th><th>Immutable snapshot</th><th>Status / audit</th><th>Action</th></tr></thead><tbody><?php foreach($closures as $row):$snap=json_decode((string)$row['summary_snapshot'],true)?:[];?><tr><td><strong><?=e(date('d M Y',strtotime((string)$row['business_date'])))?></strong></td><td><strong><?=e($row['vendor_name'])?></strong></td><td><?=e(date('H:i',strtotime((string)$row['closed_at'])))?><span class="muted-text">by <?=e((string)($row['closed_by']??'Unknown'))?></span></td><td><details class="close-day-snapshot"><summary><?=number_format((int)($snap['sale_count']??0))?> sales · <?=e(closure_money($snap['net_sales']??0))?> net</summary><span class="muted-text">Gross <?=e(closure_money($snap['gross_sales']??0))?> · Delivery <?=e(closure_money($snap['delivery_charges']??0))?> · Discount/commission <?=e(closure_money($snap['discounts_commissions']??0))?> · Final <?=e(closure_money($snap['amount_less_commission']??0))?></span><?php foreach(($snap['products']??[]) as $product):?><span class="muted-text"><?=e($product['brand_name'].' '.$product['plug_number'])?> × <?=number_format((int)$product['quantity'])?></span><?php endforeach;?><?php foreach(($snap['personnel']??[]) as $person):?><span class="muted-text"><?=e($person['personnel_name'])?>: <?=number_format((int)$person['sale_count'])?> sales, <?=e(closure_money($person['net_sales']))?> net</span><?php endforeach;?></details></td><td><?php if($row['reopened_at']):?><span class="status-badge is-warning">Reopened</span><span class="muted-text"><?=e(date('d M Y H:i',strtotime((string)$row['reopened_at'])))?> by <?=e((string)$row['reopened_by'])?><br><?=e((string)$row['reopen_reason'])?></span><?php else:?><span class="status-badge is-inactive">Closed</span><?php endif;?></td><td><?php if(!$row['reopened_at']):?><form class="close-day-reopen" method="post" data-confirm-title="Reopen this vendor day?" data-confirm-message="The vendor owner and assigned personnel will be able to record sales again today only if this is the current business date."><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="reopen"><input type="hidden" name="closure_id" value="<?=(int)$row['id']?>"><input name="reason" required maxlength="1000" aria-label="Reopening reason" placeholder="Required reason"><button class="action-button" type="submit" title="Reopen day"><i class="fa-solid fa-lock-open"></i></button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?><?php if(!$closures):?><tr><td colspan="6" class="empty-state">No vendor day closures recorded.</td></tr><?php endif;?></tbody></table></div>
<?php endif;?></section>
<?php if($auditView&&$auditMode!==''):?>
<script>
document.querySelectorAll('[data-pos-live-filter]').forEach(function (form) {
    var timer;
    if (form.dataset.posLiveFilter === 'search') {
        var search = form.querySelector('input[type="search"]');
        if (!search) return;
        search.addEventListener('input', function () {
            window.clearTimeout(timer);
            timer = window.setTimeout(function () { form.requestSubmit(); }, 450);
        });
    } else {
        form.querySelectorAll('input[type="date"]').forEach(function (field) {
            field.addEventListener('change', function () {
                window.clearTimeout(timer);
                timer = window.setTimeout(function () { form.requestSubmit(); }, 120);
            });
        });
    }
});
</script>
